:root {
  --ink: #243449;
  --paper: #fffdf6;
  --coral: #e8755b;
}

.token {
  width: 440px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background-color: var(--paper);
  color: var(--ink);
}

.token-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background-color: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.4px;
}

.token-mark {
  color: var(--coral);
  font-size: 18px;
}

.admission {
  padding: 18px 16px;
}

.admission p {
  margin: 0 0 5px;
  color: var(--coral);
  font-size: 14px;
  font-weight: 700;
}

.admission strong {
  font-size: 24px;
  letter-spacing: 0.4px;
}

.token-foot {
  display: flex;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 2px dashed var(--coral);
  font-size: 13px;
  font-weight: 700;
}
